import { writeFileSync } from 'node:fs';
import { loadLinks } from '../src/links.js';

/** Regenerates docs/links.md from data/links.yaml. */
const links = loadLinks();
const byCategory = new Map<string, typeof links>();
for (const l of links) byCategory.set(l.category, [...(byCategory.get(l.category) ?? []), l]);

const lines = [
  '# Official link catalog',
  '',
  '<!-- Generated by `pnpm links:md` from data/links.yaml — do not edit by hand. -->',
  '',
  `${links.length} official METU pages. "Login" shows the system a student must sign in to.`,
  '',
];
for (const [category, list] of [...byCategory.entries()].sort()) {
  lines.push(`## ${category}`, '', '| Page | Login | Note |', '|---|---|---|');
  for (const l of list) {
    lines.push(`| [${l.title.en}](${l.url}) / ${l.title.tr} | ${l.requires_auth || '—'} | ${l.note.en} |`);
  }
  lines.push('');
}
writeFileSync(new URL('../docs/links.md', import.meta.url), lines.join('\n'));
console.log(`docs/links.md: ${links.length} links`);
